-- Checkout caches the postcode list by this version; a new one makes browsers fetch the Bangla names.
UPDATE settings SET value = CAST(CAST(value AS INTEGER) + 1 AS TEXT), updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE key = 'geo_postcode_version';
